<?php $job=value('SELECT id FROM crawl_jobs WHERE website_id=? AND status="completed" ORDER BY id DESC LIMIT 1',[$wid]);$page=max(1,min(10000,(int)($_GET['page']??1)));$records=$job?rows('SELECT * FROM pages WHERE job_id=? ORDER BY id LIMIT 25 OFFSET '.(($page-1)*25),[$job]):[];?><div class="card"><h3>Crawled pages</h3><p class="small">Metadata and page measurements from the latest completed crawl.</p><?php table(['url'=>'URL','http_status'=>'HTTP','title'=>'Title','h1'=>'H1','word_count'=>'Words','score'=>'Score'],$records);?><nav class="pagination"><?php if($page>1):?><a href="?website_id=<?=$wid?>&page=<?=$page-1?>">Previous</a><?php endif;if(count($records)===25):?><a href="?website_id=<?=$wid?>&page=<?=$page+1?>">Next</a><?php endif;?></nav></div><?php foreach($records as $p):?><details class="card stack"><summary><?=e($p['url'])?> — metadata details</summary><?php table(['description'=>'Description','h2'=>'H2','canonical'=>'Canonical','robots'=>'Robots','image_count'=>'Images','missing_alt'=>'Missing alt','schema_count'=>'JSON-LD','og_count'=>'Open Graph','load_ms'=>'Fetch ms'],[$p]);?><p class="small">Internal links</p><pre><?=e(implode("\n",json_decode($p['internal_links'],true)??[]))?></pre><p class="small">External links</p><pre><?=e(implode("\n",json_decode($p['external_links'],true)??[]))?></pre></details><?php endforeach;?>
